  "source": "https://github.com/x2ansible/puppet-examples",
  "dependencies": [
    { "name": "puppetlabs-stdlib", "version_requirement": ">= 9.0.0 < 10.0.0" },
    { "name": "puppetlabs-apt", "version_requirement": ">= 9.0.0 < 10.0.0" }
  ],
  "operatingsystem_support": [
    { "operatingsystem": "Ubuntu", "operatingsystemrelease": ["24.04"] },
